"""Retain evidence regenerated by the existing suites in this delivery's own folder."""
from pathlib import Path
import json, shutil
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'docs/history/implementation-passes/actors-combat-concept-world'
sources={
 'chapter01-r2-actors-v2-integration':['animated-clearance.json','route-arena-clearance.json','death-respawn.txt','actor-traversal.txt','encounter-animation.txt'],
 'chapter01-complete-concept':['chapter-five-minute-soak.json','chapter-traversal.txt','encounters-save.txt','chapter-contract.json','player-silhouette.json'],
 'capacitor-field-proof':['sector-traversal.txt','functional-flow.txt'],
}
receipts=[]
for folder,names in sources.items():
    for name in names:
        source=ROOT/'docs/history/implementation-passes'/folder/'verification'/name
        target=OUT/'verification'/(folder+'--'+name)
        shutil.copyfile(source,target)
        receipts.append(dict(source=source.relative_to(ROOT).as_posix(),retained=target.relative_to(ROOT).as_posix(),modifiedUtc=source.stat().st_mtime))
# Actual encounter articulation captures, generated by this run, are distinct from the posed comparison board.
gallery=ROOT/'docs/history/implementation-passes/chapter01-r2-actors-v2-integration/gallery'
for source in gallery.glob('*.png'):
    if source.stat().st_mtime < 1791806400: continue # 2026-10-12 UTC, excludes previous deliveries
    target=OUT/'actual-animation'/source.name;target.parent.mkdir(exist_ok=True)
    shutil.copyfile(source,target)
    receipts.append(dict(source=source.relative_to(ROOT).as_posix(),retained=target.relative_to(ROOT).as_posix(),modifiedUtc=source.stat().st_mtime))
(OUT/'verification/retained-evidence.json').write_text(json.dumps(receipts,indent=2))
print('Retained current QA evidence:',len(receipts))
